{{-- Wizard-style form chrome, mirroring the RFQ add/edit form (rfqs/_form.blade.php). --}}
<style>
    .vendor-form { max-width: 1180px; margin: 0 auto; }
    .vendor-form__intro { display:flex; align-items:flex-start; justify-content:space-between; gap:24px; padding:22px 24px; margin-bottom:18px; border:1px solid var(--border); border-radius:16px; background:linear-gradient(135deg,rgba(7,41,73,.14),var(--surface)); }
    .vendor-form__intro h2 { margin:0; font-size:20px; letter-spacing:-.02em; } .vendor-form__intro p { margin:5px 0 0; color:var(--muted); font-size:13px; }
    .vendor-form__intro-badge { display:inline-flex; align-items:center; gap:7px; color:var(--blue); font-size:12px; font-weight:700; white-space:nowrap; } .vendor-form__intro-badge::before { content:''; width:8px; height:8px; border-radius:50%; background:currentColor; box-shadow:0 0 0 5px rgba(96,165,250,.12); }
    .vendor-section { padding:24px; margin-bottom:18px; border:1px solid var(--border); border-radius:16px; background:var(--panel); box-shadow:var(--shadow); }
    .vendor-section__header { display:flex; align-items:flex-start; gap:12px; margin-bottom:20px; } .vendor-section__number { display:grid; place-items:center; min-width:30px; height:30px; padding:0 6px; border-radius:9px; background:rgba(14,95,149,.14); color:var(--pms-navy); font-size:13px; font-weight:800; } .vendor-section__header h3 { margin:0; font-size:17px; letter-spacing:-.01em; } .vendor-section__header p { margin:3px 0 0; color:var(--muted); font-size:13px; }
    .vendor-grid { display:grid; grid-template-columns:repeat(12,minmax(0,1fr)); gap:0 16px; } .vendor-grid__field { grid-column:span 4; } .vendor-grid__field--wide { grid-column:span 6; } .vendor-grid__field--full { grid-column:1/-1; } .vendor-grid .field { margin-bottom:18px; } .vendor-grid .field label { display:flex; align-items:center; gap:5px; } .vendor-grid .field label abbr,.vendor-form__footer abbr { color:var(--danger); text-decoration:none; } .vendor-grid input,.vendor-grid select,.vendor-grid textarea { min-height:42px; } .vendor-grid textarea { resize:vertical; min-height:92px; }
    .vendor-grid .field label.check { display:flex; }
    .vendor-form__footer { display:flex; align-items:center; justify-content:space-between; gap:16px; padding:16px 20px; margin-top:4px; border:1px solid var(--border); border-radius:14px; background:var(--panel); box-shadow:var(--shadow); } .vendor-form__footer-note { color:var(--muted); font-size:12px; } .vendor-form__footer .actions { display:flex; gap:8px; flex-wrap:wrap; }
    @media (max-width:1050px) { .vendor-grid__field,.vendor-grid__field--wide { grid-column:span 6; } }
    @media (max-width:680px) { .vendor-form__intro,.vendor-form__footer { align-items:stretch; flex-direction:column; } .vendor-section { padding:18px; } .vendor-grid__field,.vendor-grid__field--wide { grid-column:1/-1; } .vendor-form__footer .actions { width:100%; } .vendor-form__footer .actions .btn { flex:1; } }
</style>
